query:
CREATE TABLE `clickAnalytics` (
	`id` int AUTO_INCREMENT NOT NULL,
	`productId` int NOT NULL,
	`userId` varchar(64),
	`action` varchar(64) NOT NULL,
	`timestamp` timestamp NOT NULL DEFAULT (now()),
	CONSTRAINT `clickAnalytics_id` PRIMARY KEY(`id`)
);
CREATE TABLE `embedVariants` (
	`id` int AUTO_INCREMENT NOT NULL,
	`testId` varchar(255) NOT NULL,
	`variantName` varchar(255) NOT NULL,
	`embedData` json NOT NULL,
	`clicks` int NOT NULL DEFAULT 0,
	`conversions` int NOT NULL DEFAULT 0,
	`status` enum('active','inactive') NOT NULL DEFAULT 'active',
	`createdAt` timestamp NOT NULL DEFAULT (now()),
	`updatedAt` timestamp NOT NULL DEFAULT (now()) ON UPDATE CURRENT_TIMESTAMP,
	CONSTRAINT `embedVariants_id` PRIMARY KEY(`id`)
);
ALTER TABLE `paymentTransactions` DROP INDEX `paymentTransactions_externalId_unique`;
ALTER TABLE `paymentTransactions` MODIFY COLUMN `provider` enum('stripe','pix') NOT NULL;
ALTER TABLE `paymentTransactions` MODIFY COLUMN `status` enum('pending','succeeded','failed','cancelled') NOT NULL;
ALTER TABLE `botConfigs` ADD `showcaseChannelId` varchar(64);
ALTER TABLE `botConfigs` ADD `announcementChannelId` varchar(64);
ALTER TABLE `botConfigs` ADD `promotionChannelId` varchar(64);
ALTER TABLE `orders` ADD `deliveryStatus` enum('pending','sent','failed') DEFAULT 'pending' NOT NULL;
ALTER TABLE `orders` ADD `deliveryAttempts` int DEFAULT 0 NOT NULL;
ALTER TABLE `orders` ADD `lastDeliveryAttempt` timestamp;
ALTER TABLE `products` ADD `assetKey` varchar(255);
ALTER TABLE `products` ADD `isDigital` boolean DEFAULT false NOT NULL;
ALTER TABLE `clickAnalytics` ADD CONSTRAINT `clickAnalytics_productId_products_id_fk` FOREIGN KEY (`productId`) REFERENCES `products`(`id`) ON DELETE no action ON UPDATE no action;
CREATE INDEX `clickAnalytics_productId_idx` ON `clickAnalytics` (`productId`);
CREATE INDEX `clickAnalytics_userId_idx` ON `clickAnalytics` (`userId`);
CREATE INDEX `embedVariants_testId_idx` ON `embedVariants` (`testId`);
CREATE INDEX `orders_deliveryStatus_idx` ON `orders` (`deliveryStatus`);

